import '../../../../../../Core/Models/product_details_model.dart';import '../../../../../../Core/Models/product_model.dart';import '../../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../../Core/Storage/Remote/api_service.dart';import '../../../../../Global/Authentication/data/entities/user_data_model.dart';import '../models/product_preview_entities.dart';class HomeData {  static Future<List<ProductPreviewEntities>> getDataProductIsFeatured() async {    final response = await DioHelper.getData(      path: ApiEndpoints.productFeatured,    );    if (response == null || response.data["data"] == null) {      return [];    }    return (response.data["data"] as List)        .map(          (item) => ProductPreviewEntities.fromProduct(        ProductModel.fromJson(item),      ),    )        .toList();  }  static Future<List<ProductPreviewEntities>> getDataProductIsPopular() async {    final response = await DioHelper.getData(      path: ApiEndpoints.productPopular,    );    if (response == null || response.data["data"] == null) {      return [];    }    return (response.data["data"] as List)        .map(          (item) => ProductPreviewEntities.fromProduct(        ProductModel.fromJson(item),      ),    )        .toList();  }  static Future<ProductDetailsModel> getProductsByID(int id) async {    final response = await DioHelper.postData(      data: id,      path: ApiEndpoints.productDetails,    );    return (response?.data["data"]).map(          (item) => ProductDetailsModel.fromJson(        item,      ),    );  }  static Future<UserDataModel> getUserData() async {    final response = await DioHelper.getData(      path: ApiEndpoints.profileUser,    );    return UserDataModel.fromJson((response?.data["user"]));  }}